package co.com.empresa.infrastructure.repository.type;import co.com.empresa.domain.type.Type;import co.com.empresa.infrastructure.adapters.output.repositories.command.type.ITypeCommandJpaRepository;import co.com.empresa.infrastructure.adapters.output.repositories.query.type.ITypeQueryJpaRepository;import co.com.empresa.infrastructure.entities.type.TypeEntity;import co.com.empresa.infrastructure.type.TypeInfrastructureMapper;import co.com.empresa.infrastructure.type.TypeRepositoryImpl;import org.junit.jupiter.api.BeforeEach;import org.junit.jupiter.api.DisplayName;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.InjectMocks;import org.mockito.Mock;import org.mockito.junit.jupiter.MockitoExtension;import java.time.LocalDateTime;import java.util.Optional;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.ArgumentMatchers.any;import static org.mockito.Mockito.verify;import static org.mockito.Mockito.when;@ExtendWith(MockitoExtension.class)class TypeRepositoryTest {    @Mock    private ITypeQueryJpaRepository queryJpaRepository;    @Mock    private ITypeCommandJpaRepository commandJpaRepository;    @Mock    private TypeInfrastructureMapper mapper;    @InjectMocks    private TypeRepositoryImpl typeRepository;    private Type typeModel;    private TypeEntity typeEntity;    @BeforeEach    void setUp() {        typeModel = Type.builder()                .id(1L)                .typeCategoryId(1L)                .name("Test Type")                .code("TEST-001")                .description("Test Description")                .active(true)                .build();        typeEntity = TypeEntity.builder()                .id(1L)                .typeCategoryId(1L)                .name("Test Type")                .code("TEST-001")                .description("Test Description")                .active(true)                .createBy("system")                .createDate(LocalDateTime.now())                .build();    }    @Test    @DisplayName("save: Should persist entity and return mapped model")    void save_Success() {        when(mapper.modelToEntity(any())).thenReturn(typeEntity);        when(commandJpaRepository.save(any())).thenReturn(typeEntity);        when(mapper.entityToModel(any())).thenReturn(typeModel);        Type result = typeRepository.save(typeModel);        assertNotNull(result);        verify(commandJpaRepository).save(any());    }    @Test    @DisplayName("findById: Should return model when entity exists")    void findById_Exists_ReturnsModel() {        Long id = 1L;        when(queryJpaRepository.findById(id)).thenReturn(Optional.of(typeEntity));        when(mapper.entityToModel(typeEntity)).thenReturn(typeModel);        Optional<Type> result = typeRepository.findById(id);        assertTrue(result.isPresent());        assertEquals(typeModel, result.get());    }    @Test    @DisplayName("findById: Should return empty when entity not found")    void findById_NotFound_ReturnsEmpty() {        Long id = 999L;        when(queryJpaRepository.findById(id)).thenReturn(Optional.empty());        Optional<Type> result = typeRepository.findById(id);        assertTrue(result.isEmpty());    }}